def stabilize_per_test(config: TestRunnerConfig, tests: list[TestCase]) -> bool:
    # Rerun each test on its own, once per its group's rerun count. Returns True if any
    # individual rerun reported a non-zero exit code.
    any_failure = False
    for test in tests:
