    return any_failure


def stabilize_full_set(config: TestRunnerConfig, tests: list[TestCase], reruns: int) -> bool:
    # Rerun the entire set of tests `reruns` times. Returns True if any rerun failed.
    any_failure = False
    batch_size = compute_batch_size(len(tests), config)
    batches = list(chunked(tests, batch_size))
    for _ in range(reruns):
        if stop_requested():
            return any_failure
        result = run_tests(config, batches, len(tests))
        if result.returncode != 0:
            any_failure = True
    return any_failure


def unique_ordered_tests(tests: list[TestCase], names: set) -> list[TestCase]:
    # Preserve list order while keeping only tests whose name is in `names`, without duplicates.
    seen = set()
    selected = []
    for test in tests:
        if test.name in names and test.name not in seen:
            seen.add(test.name)
            selected.append(test)
    return selected


def perform_stabilization(args, config: TestRunnerConfig, tests: list[TestCase], base_names: set | None) -> bool:
    # Rerun tests to shake out flakiness after the initial run. Returns True if any rerun failed.
    if args.changed_tests is not None:
        new_names = {test.name for test in tests} - (base_names or set())
        new_tests = unique_ordered_tests(tests, new_names)
        if not new_tests:
            return False
        if len(new_tests) > STABILIZE_NEW_TESTS_PER_TEST_LIMIT:
            # Too many new tests to rerun individually: rerun the whole new set a few times.
            return stabilize_full_set(config, new_tests, STABILIZE_NEW_TESTS_FULL_RERUNS)
        return stabilize_per_test(config, new_tests)
    if args.stabilize_tests and args.test_list is not None:
        return stabilize_per_test(config, tests)
    return False


